mapper.select:
select mx.*, dc.DICVALUE as careTypeName,dc2.DICVALUE as helpformTypeName from DJ_DNGHBFMX mx inner join DJ_dnghbf p on mx.DNGHBFID=p.ID left join CF_DICTIONARY dc on p.careType=dc.DICKEY and dc.DICTYPEKEY='povertyType' left join CF_DICTIONARY dc2 on mx.helpformType=dc2.DICKEY and dc2.DICTYPEKEY='helpformType' where 1=1
and p.id =#{dnbfid}
and p.dzzdm like concat('%',#{dzzdm},'%')
and p.DZZMC like concat('%',#{dzzmc},'%')
and p.username like concat('%',#{username},'%')
and p.userid =#{userid}
and p.careType = #{careType}
and SUBSTR(p.dzzdm,1,12) in(select dzzdm from ZZ_DZZFBQK where zzfb= #{zzfbType})
order by mx.CAREDATE desc

select p.DZZMC,p.USERNAME,p.USERID,mx.*, dc.DICVALUE as careTypeName,dc2.DICVALUE as helpformTypeName from DJ_DNGHBFMX mx inner join DJ_dnghbf p on mx.DNGHBFID=p.ID left join CF_DICTIONARY dc on p.careType=dc.DICKEY and dc.DICTYPEKEY='povertyType' left join CF_DICTIONARY dc2 on mx.helpformType=dc2.DICKEY and dc2.DICTYPEKEY='helpformType' where 1=1
and mx.id =#{dnbfmxid}
order by mx.CAREDATE desc

select p.*,dc.DICVALUE as judgeLevelName,dy.DICVALUE as yearName from DJ_djkpxx p inner join ZZ_ZZQKXX zz on p.DZZDM=zz.DZZDM left join ZZ_ZZQKXXFB cfb on zz.DZZDM=cfb.DZZDM left join CF_DICTIONARY dc on p.judgeLevel=dc.DICKEY and dc.DICTYPEKEY='judgeLevel' left join CF_DICTIONARY dy on p.YEAR=dc.DICKEY and dc.DICTYPEKEY='years' where 1=1
and p.dzzdm like concat('',#{dzzdm},'%')
and p.DZZMC like concat('%',#{dzzmc},'%')
and p.judgeLevel = #{judgeLevel}
and p.year = #{year}
and SUBSTR(p.dzzdm,1,12) in(select dzzdm from ZZ_DZZFBQK where zzfb= #{zzfbType})
and p.dzzdm =#{ssdzzdm}
and cfb.zzlb in('100','200')
and cfb.zzlb not in('100','200')
order by p.updateTime desc

select tk.*,(select count(1) from DJ_taskUsers dtu where dtu.taskid=tk.id) USERNAME, (select count(1) from DJ_taskUsers us where us.taskid=tk.id and us.Isreceive=1
and us.userid=#{taskuserid}
) "isreceive" from DJ_task tk left join (select taskid, group_concat(USERNAME ORDER BY USERNAME,',') as USERNAME from DJ_taskUsers group by taskid) ry on tk.id=ry.taskid where 1=1
and ry.username like concat('%',#{username},'%')
and #{taskuserid} in (select userid from DJ_taskUsers t where t.taskid=tk.ID)
and tk.CREATEUSERID= #{userid}
and tk.taskName like concat('%',#{taskName},'%')
and tk.endTime >= date_format(#{beginTime},'%Y%m%d')
and tk.endTime < date_add(date_format(#{endTime},'%Y%m%d'),interval 1 day)
and date_format(tk.endTime,'%Y-%m-%d') = #{day}
and (select count(1) from DJ_taskUsers us where us.taskid=tk.id and ifnull( us.Isreceive,0)=#{isreceive}) and us.userid=#{taskuserid})=1
order by tk.endTime desc

select zz.DZZMC,ry.XM, p.*,pyjg.HZMC as PYJGMC from ZZ_MZPYXX p
inner join ZZ_ZZQKXX zz on p.SZDZBDM=ZZ.DZZDM
inner join VM_RYJBXX ry on p.RYBM = ry.RYBM
inner join ZZZD_PYJG pyjg on p.PYJG=pyjg.BM
where 1=1

    and p.rybm = #{rybm}


    and p.kzpyrq  >=  #{beginTime}


    and p.jspyrq  <=  #{endTime}


    and ry.xm like concat('%',#{username},'%')


    and p.SZDZBDM like concat('%',#{dzzdm},'%')


    and p.pyjg = #{pyjg}

order by p.KZPYRQ desc

select rs.RYBM,rs.DZZMC,rs.XM from ( select * from ( select y.RYBM,u.XM,uz.DZZMC,y.ZLYTYPE from ZZ_DZZZLY y inner join VM_RYJBXX u on y.RYBM = u.RYBM inner join ZZ_ZZQKXX uz on u.SZDZBDM = uz.dzzdm union all select c.RYBM, u.XM, uz.DZZMC, 6 ZLYTYPE from ZZ_BZCYXX c inner join ZZ_ZZQKXX z on c.dzzdm = z.dzzdm inner join ZZ_ZZQKXXFB dzzfb on c.DZZDM = dzzfb.DZZDM and c.JC = dzzfb.LDJTJC left join Zzzd_zwmc zwmc on c.zwmc = zwmc.bm inner join VM_RYJBXX u on c.RYBM = u.RYBM inner join ZZ_ZZQKXX uz on u.SZDZBDM = uz.dzzdm where c.zwmc in ('H001', 'H040') ) p where 1=1
and p.ZLYTYPE =#{usertype}
and p.xm like concat('%',#{username},'%')
) rs group by rs.RYBM,rs.DZZMC,rs.XM
